{"task": "Count events whose path contains a full date segment like /YYYY/MM/DD/", "sql": "SELECT COUNT(*) AS date_path_count FROM events WHERE regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/')"}
{"task": "List distinct dated paths found in events for manual review", "sql": "SELECT DISTINCT path FROM events WHERE regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') ORDER BY path"}
{"task": "Extract the year/month/day segment from dated paths and count occurrences per date", "sql": "SELECT regexp_match(path, '/([0-9]{4}/[0-9]{2}/[0-9]{2})/') AS date_part, COUNT(*) AS cnt FROM events WHERE regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') GROUP BY date_part ORDER BY cnt DESC"}
{"task": "Find error-status requests to dated paths to spot broken archive links", "sql": "SELECT path, status FROM events WHERE status >= 400 AND regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') ORDER BY status DESC"}
{"task": "Flag log lines that reference a dated path in the free-text message", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') ORDER BY ts DESC LIMIT 100"}
{"task": "Categorize each event path as dated or non-dated using a CASE expression with regexp_like", "sql": "SELECT path, CASE WHEN regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') THEN 'dated' ELSE 'non_dated' END AS path_type FROM events"}
{"task": "Find requests to today's date path (2026/10/25) specifically", "sql": "SELECT path, status FROM events WHERE regexp_like(path, '^/2026/10/25/') ORDER BY path"}
{"task": "Detect malformed date-like paths with an invalid month value (00 or >12) for data quality checks", "sql": "SELECT path FROM events WHERE regexp_like(path, '/[0-9]{4}/') AND regexp_like(path, '/[0-9]{4}/(00|1[3-9])/')"}
{"task": "Identify users who hit dated archive paths, joined with their event status codes", "sql": "SELECT user_id, path, status FROM events WHERE regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') ORDER BY user_id"}
{"task": "Correlate error logs with dated-path events by matching the date substring in both the log message and the request path", "sql": "SELECT l.ts, l.service, l.message, e.path, e.status FROM logs l JOIN events e ON regexp_like(l.message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') AND regexp_like(e.path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') AND l.message LIKE '%' || substring(e.path FROM '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') || '%' WHERE l.level = 'ERROR'"}

